// Delivers the application itself — but only to a signed-in user. Before login the
// browser receives just a small login page (index.html); the real app code never
// sits in a public file. The code is stored (obfuscated + gzipped) in _app.js.

import { verifySession } from "./_auth.js";
// The packed application (gzip + base64) is kept inside this file so the function has no extra module to resolve.
const APP_GZ_B64 = "";

export const config = { runtime: "edge" };

// Return decoded HTML and let the hosting platform manage transport compression.
// Pre-compressed response bodies can reach fetch().text() as binary on Vercel.
let cachedHtml = null;
async function appHtml() {
  if (cachedHtml === null) {
    const bytes = Uint8Array.from(atob(APP_GZ_B64), (c) => c.charCodeAt(0));
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
    cachedHtml = await new Response(stream).text();
  }
  return cachedHtml;
}

export default async function handler(request) {
  const noStore = { "Cache-Control": "no-store, private", "X-Robots-Tag": "noindex, nofollow" };
  if (request.method !== "GET") return new Response("Method not allowed", { status: 405, headers: { Allow: "GET", ...noStore } });
  const session = await verifySession(request);
  if (!session) return new Response(JSON.stringify({ error: "Please sign in." }), { status: 401, headers: { "Content-Type": "application/json", ...noStore } });
  return new Response(await appHtml(), { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", ...noStore } });
}
